import '../models/barbershop_models.dart';

class ScheduleTemplate {
  const ScheduleTemplate({required this.id,required this.name,required this.description,required this.days,this.slotIntervalMinutes=30});
  final String id,name,description; final List<DaySchedule> days; final int slotIntervalMinutes;
  BarbershopSchedule createSchedule({required String scheduleId,required String barbershopId})=>BarbershopSchedule(id:scheduleId,barbershopId:barbershopId,templateId:id,days:[for(final day in days)day.copyWith()],slotIntervalMinutes:slotIntervalMinutes);
}
